import argparse
import os
import sys

from workpeg import build, cdn, create_new, run, runtime, submit
from workpeg.terminal import shown_lines


# The package's, not a second copy of the same lookup. Keeping its own was
# how `workpeg --version` stayed correct for years while `workpeg.__version__`
# reported 0.1.0 — two answers to one question, and only one of them wrong.
from workpeg import __version__


# Mirrors workpeg.ui.build.CHROME_SOURCES, spelled out rather than imported:
# pulling in the UI compiler here would cost every CLI invocation ~100ms,
# which is why build_ui is imported lazily in the ui.build handler.
# test_cli.py pins the two lists together.
_CHROME_SOURCES = ("auto", "bundled")


def _add_runner_options(parser: argparse.ArgumentParser) -> None:
    """The function runner's options, on ``project serve`` and on ``ui
    serve`` beside ``--listen``. None reaches the page or its build."""
    parser.add_argument(
        "--with",
        dest="with_runtime",
        choices=("docker", "process"),
        default=None,
        help=(
            "Where your function runs for your own saves:\n"
            "  docker   (default) its own Dockerfile, on 127.0.0.1 behind a\n"
            "           random invoke key, removed when this stops\n"
            "  process  python -m workpeg.runtime in its folder, as you,\n"
            "           with everything you can read: only for code you\n"
            "           wrote yourself"
        ),
    )
    parser.add_argument(
        "--concurrency",
        type=int,
        default=None,
        metavar="N",
        help="Calls run at once, 1 or 2 (default: 2, the API's cap)",
    )
    parser.add_argument(
        "--show-payload",
        action="store_true",
        help="Print each call's envelope, its token replaced by <token>",
    )
    parser.add_argument(
        "--debug",
        action="store_true",
        help=(
            "With --with process: one call at a time, with this terminal,\n"
            "so breakpoint() works"
        ),
    )


def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(
        prog="workpeg",
        description=(
            "Workpeg CLI\n\n"
            "Build, run, and publish Workpeg Pegs and assets."
        ),
        formatter_class=argparse.RawTextHelpFormatter,
        epilog=(
            "Examples:\n"
            "  workpeg function new hello\n"
            "  workpeg function build\n"
            "  workpeg function run --with docker\n"
            "  workpeg function test my-peg/\n"
            "  workpeg function submit 1.0.0          (dev, not reviewed)\n"
            "  workpeg function submit main:1.0.0     (release, reviewed)\n"
            "  workpeg cdn submit ./dist\n"
            "  workpeg cdn submit ex.png\n"
            "  workpeg ui new counter\n"
            "  workpeg ui serve counter/\n"
            "  workpeg ui build counter/\n"
            "  workpeg doctor\n"
            "\n"
            "Use 'workpeg <namespace> --help' for more information.\n"
        ),
    )

    p.add_argument(
        "-v",
        "--version",
        action="version",
        version=f"workpeg {__version__}",
    )

    root_sub = p.add_subparsers(
        dest="namespace",
        metavar="{function,cdn,ui,doctor}",
    )

    #
    # FUNCTION
    #

    function_p = root_sub.add_parser(
        "function",
        help="Manage Workpeg Functions",
        formatter_class=argparse.RawTextHelpFormatter,
    )

    function_p.set_defaults(_namespace_parser=function_p)

    function_sub = function_p.add_subparsers(
        dest="command",
        metavar="{new,build,run,runtime,test,submit}",
    )

    new_p = function_sub.add_parser(
        "new",
        help="Create a new function project",
    )
    new_p.add_argument("path")
    new_p.add_argument("--force", action="store_true")
    new_p.set_defaults(_handler="function.new")

    runtime_p = function_sub.add_parser(
        "runtime",
        help="Run the raw function runtime",
    )
    runtime_p.add_argument("--server", action="store_true")
    runtime_p.set_defaults(_handler="function.runtime")

    build_p = function_sub.add_parser(
        "build",
        help="Build the function Docker image",
    )
    build_p.add_argument("--path", default=".")
    build_p.add_argument("--tag", default=None)
    build_p.add_argument(
        "--like-workpeg",
        action="store_true",
        help="build as Workpeg's install does: --pull, no network for any "
             "RUN step, and linux/amd64",
    )
    build_p.set_defaults(_handler="function.build")

    run_p = function_sub.add_parser(
        "run",
        help="Run the function using a configured runtime",
    )
    run_p.add_argument(
        "--with",
        dest="with_runtime",
        choices=["docker", "cracker"],
    )
    run_p.add_argument("--path", default=".")
    run_p.add_argument("--no-build", action="store_true")
    run_p.add_argument("--network", default=None)
    run_p.add_argument("--name", default=None)
    run_p.add_argument("--no-expose", action="store_true")
    run_p.set_defaults(_handler="function.run")

    # There is no `function listen` and no `function call` (owner,
    # 2026-11-11): a dev install's function runs from the command that
    # serves its page, `workpeg project serve <peg> --fake-cloud`, and no
    # command trades a key for a token. tests/test_function_listen.py holds
    # both names refused.
    test_p = function_sub.add_parser(
        "test",
        help="Run the function once, offline, with a platform envelope",
        formatter_class=argparse.RawTextHelpFormatter,
        description=(
            "Run the function once in a child process with the envelope the\n"
            "platform would send, a placeholder token and the test business,\n"
            "and print its answer. Nothing is sent anywhere."
        ),
        epilog=(
            "Examples:\n"
            "  workpeg function test my-peg/\n"
            "  workpeg function test my-peg/ --phase post_save --payload row.json\n"
            "  workpeg function test my-peg/function/ --envelope agent\n"
            "  workpeg function test . --envelope action --action archive\n"
        ),
    )
    test_p.add_argument(
        "path", nargs="?", default=".",
        help="The peg's folder, or its function folder (default: .)")
    test_p.add_argument(
        "--envelope", choices=("row", "agent", "action"), default="row",
        help=("row: a Tables API save (default); agent: a row Workpeg AI\n"
              "wrote; action: a manifest action with a phase"))
    test_p.add_argument(
        "--phase", choices=("pre_save", "post_save"), default="pre_save",
        help="pre_save (default) or post_save")
    test_p.add_argument(
        "--action", default=None, metavar="NAME",
        help="The action's name, for --envelope action")
    test_p.add_argument(
        "--payload", default=None, metavar="FILE",
        help="A JSON object: the row's data, or the action's arguments")
    test_p.add_argument(
        "--timeout", type=float, default=30.0, metavar="SECONDS",
        help="How long the call may take (default: 30)")
    test_p.set_defaults(_handler="function.test")

    submit_p = function_sub.add_parser(
        "submit",
        help="Upload a function bundle (dev by default; main is reviewed)",
        description=(
            "Upload a function bundle. A bare version goes to the 'dev' "
            "branch; 'main:<version>' submits a release for Workpeg's "
            "review."
        ),
    )
    submit_p.add_argument("ref", help=submit.REF_HELP)
    submit_p.add_argument("--branch", default=None, help=submit.BRANCH_HELP)
    submit_p.add_argument("--api", default=None)
    submit_p.add_argument("--path", default=None)
    submit_p.add_argument("--timeout", type=int, default=None)
    submit_p.set_defaults(_handler="function.submit")

    #
    # CDN
    #

    cdn_p = root_sub.add_parser(
        "cdn",
        help="Manage Peg CDN assets",
        formatter_class=argparse.RawTextHelpFormatter,
    )

    cdn_p.set_defaults(_namespace_parser=cdn_p)

    cdn_sub = cdn_p.add_subparsers(
        dest="command",
        metavar="{submit}",
    )

    cdn_submit_p = cdn_sub.add_parser(
        "submit",
        help="Submit files or directories to the Peg CDN",
        formatter_class=argparse.RawTextHelpFormatter,
        epilog=(
            "Examples:\n"
            "  workpeg cdn submit ex.png\n"
            "  workpeg cdn submit ./dist\n"
            "  workpeg cdn submit .\n"
            "  workpeg cdn submit ./dist --path assets\n"
            "  workpeg cdn submit ./dist --path archives/dist.tar.gz --exact\n"
            "  workpeg cdn submit ./assets --overwrite\n"
        ),
    )

    cdn_submit_p.add_argument(
        "source",
        help="File or directory to upload",
    )

    cdn_submit_p.add_argument(
        "--path",
        default=None,
        help=(
            "Target CDN path inside the Peg namespace. "
            "Defaults to filename for files, directory name for directories, "
            "or 'assets' when source is '.'."
        ),
    )

    cdn_submit_p.add_argument(
        "--api",
        default=None,
        help="Override Workpeg registry API base URL",
    )

    cdn_submit_p.add_argument(
        "--exact",
        action="store_true",
        help="Upload archive exactly instead of extracting it",
    )

    cdn_submit_p.add_argument(
        "--overwrite",
        action="store_true",
        help="Replace existing CDN assets if they already exist",
    )

    cdn_submit_p.add_argument(
        "--timeout",
        type=int,
        default=None,
        help="HTTP request timeout in seconds",
    )

    cdn_submit_p.set_defaults(_handler="cdn.submit")

    #
    # UI
    #

    project_p = root_sub.add_parser(
        "project",
        help="Scaffold and manage a whole peg (UI + function)",
        formatter_class=argparse.RawTextHelpFormatter,
        epilog=(
            "A peg is two halves and a manifest that binds them.\n"
            "\n"
            "Examples:\n"
            "  workpeg project create my-peg\n"
            "  workpeg ui serve my-peg/ui/ --fake-cloud\n"
            "  workpeg project serve my-peg/ --fake-cloud\n"
            "  workpeg function run --path my-peg/function/\n"
        ),
    )
    project_p.set_defaults(_namespace_parser=project_p)

    project_sub = project_p.add_subparsers(
        dest="command",
        metavar="{create,serve,target,submit,status,versions}",
    )

    project_serve_p = project_sub.add_parser(
        "serve",
        help="Serve a peg's dev page and run its function for your saves",
        formatter_class=argparse.RawTextHelpFormatter,
        description=(
            "Serve <peg>/ui/ as `workpeg ui serve --fake-cloud` does, and run\n"
            "<peg>/function/ on this computer for your own actions on the\n"
            "dev install: your saves on the page, and nobody else's.\n"
            "Reads WORKPEG_PK, your Key for running your function, from the\n"
            "environment; the page itself needs no key."
        ),
        epilog=(
            "Examples:\n"
            "  WORKPEG_PK=... workpeg project serve my-peg/ --fake-cloud\n"
            "  workpeg project serve my-peg/ --fake-cloud --with process\n"
            "  workpeg project serve my-peg/ --fake-cloud --with process --debug\n"
            "\n"
            "Guide: docs/dev-install.md#your-function\n"
        ),
    )
    project_serve_p.add_argument(
        "peg", help="The peg's folder: workpeg.json, ui/ and function/")
    project_serve_p.add_argument(
        "--fake-cloud",
        action="store_true",
        help="Serve the page as a dev install (required)",
    )
    project_serve_p.add_argument(
        "--port",
        type=int,
        default=0,
        help="443 only, as `ui serve --fake-cloud`",
    )
    _add_runner_options(project_serve_p)
    project_serve_p.set_defaults(_handler="project.serve")

    project_create_p = project_sub.add_parser(
        "create",
        help="Create a peg: UI, function and manifest in one folder",
        formatter_class=argparse.RawTextHelpFormatter,
        epilog=(
            "Creates:\n"
            "  my-peg/workpeg.json   the manifest\n"
            "  my-peg/AGENTS.md      the guide for coding agents\n"
            "  my-peg/CLAUDE.md      imports AGENTS.md\n"
            "  my-peg/ui/            the interface\n"
            "  my-peg/function/      the backend\n"
            "\n"
            "The name becomes your peg's namespace and, eventually, the first\n"
            "label of <namespace>.workpeg.com — so it is checked against DNS\n"
            "rules now rather than at release.\n"
        ),
    )
    project_create_p.add_argument(
        "name", help="Peg namespace, e.g. my-peg")
    project_create_p.add_argument(
        "--path", default="",
        help="Where to create it (default: ./<name>)")
    project_create_p.add_argument(
        "--force", action="store_true",
        help="Write into a directory that already has files")
    project_create_p.set_defaults(_handler="project.create")

    project_target_p = project_sub.add_parser(
        "target",
        help="Set the SDK version Workpeg will build this peg with",
        formatter_class=argparse.RawTextHelpFormatter,
        description=(
            "Rewrite the \"sdk\" key in the peg's workpeg.json. Workpeg\n"
            "builds a released peg itself, with this exact SDK, whatever is\n"
            "installed on your computer. 0.150.0 is the lowest it builds."
        ),
        epilog=(
            "Examples:\n"
            "  workpeg project target 0.160.0\n"
            "  workpeg project target 0.160.0 --path my-peg/\n"
            "\n"
            "Guide: docs/projects.md#the-sdk-it-targets\n"
        ),
    )
    project_target_p.add_argument(
        "version", help="One exact release, X.Y.Z, e.g. 0.160.0")
    project_target_p.add_argument(
        "--path", default=".",
        help="The peg's folder, with workpeg.json (default: .)")
    project_target_p.set_defaults(_handler="project.target")

    project_submit_p = project_sub.add_parser(
        "submit",
        help="Check and send a peg's whole source as one version",
        formatter_class=argparse.RawTextHelpFormatter,
        description=(
            "Check and pack the peg's source (workpeg.json, ui/, function/,\n"
            "assets/) and upload it as one peg version, straight to\n"
            "Workpeg's private bucket. A main version is queued for\n"
            "Workpeg to build with the SDK its \"sdk\" key names, then\n"
            "reviewed; any other branch is stored for development only.\n"
            "A local build is never sent."
        ),
        epilog=(
            "Examples:\n"
            "  workpeg project submit 1.0.0 --dry-run\n"
            "  workpeg project submit 1.0.0          (dev, not reviewed)\n"
            "  workpeg project submit main:1.0.0     (release, reviewed)\n"
            "\n"
            "Reads WORKPEG_PK, the peg's Key, from the environment.\n"
            "Guide: docs/projects.md#workpeg-project-submit\n"
        ),
    )
    project_submit_p.add_argument("ref", help=submit.REF_HELP)
    project_submit_p.add_argument(
        "--path", default=".",
        help="The peg's folder, with workpeg.json (default: .)")
    project_submit_p.add_argument(
        "--dry-run", action="store_true",
        help="Check and pack, print the digest and the files, upload nothing")
    project_submit_p.add_argument("--api", default=None,
                                  help="Registry base URL")
    project_submit_p.add_argument("--timeout", type=int, default=60,
                                  help="Request timeout (seconds)")
    project_submit_p.set_defaults(_handler="project.submit")

    project_status_p = project_sub.add_parser(
        "status",
        help="Show where one version of the peg stands",
        formatter_class=argparse.RawTextHelpFormatter,
        epilog=(
            "Examples:\n"
            "  workpeg project status               (the newest release)\n"
            "  workpeg project status main:1.0.0\n"
            "\n"
            "Guide: docs/projects.md#workpeg-project-status\n"
        ),
    )
    project_status_p.add_argument(
        "ref", nargs="?", default=None,
        help="<version> (dev) or <branch>:<version>; default: the newest "
             "main version")
    project_versions_p = project_sub.add_parser(
        "versions",
        help="List every version of the peg on the registry",
        formatter_class=argparse.RawTextHelpFormatter,
        epilog="Guide: docs/projects.md#workpeg-project-versions\n",
    )
    for reader in (project_status_p, project_versions_p):
        reader.add_argument(
            "--path", default=".",
            help="The peg's folder, with workpeg.json (default: .)")
        reader.add_argument("--json", action="store_true",
                            help="Print the registry's answer as JSON")
        reader.add_argument("--api", default=None, help="Registry base URL")
        reader.add_argument("--timeout", type=int, default=60,
                            help="Request timeout (seconds)")
    project_status_p.set_defaults(_handler="project.status")
    project_versions_p.set_defaults(_handler="project.versions")

    ui_p = root_sub.add_parser(
        "ui",
        help="Compile Peg UI apps",
        formatter_class=argparse.RawTextHelpFormatter,
    )

    ui_p.set_defaults(_namespace_parser=ui_p)

    ui_sub = ui_p.add_subparsers(
        dest="command",
        metavar="{new,build,serve,verify,dev-clean}",
    )

    ui_new_p = ui_sub.add_parser(
        "new",
        help="Scaffold a counter app, compile it, and serve on localhost",
        formatter_class=argparse.RawTextHelpFormatter,
        epilog=(
            "Examples:\n"
            "  workpeg ui new counter\n"
            "  workpeg ui new my-app --port 3000\n"
            "  workpeg ui new counter --no-serve\n"
            "  workpeg ui new counter --fake-cloud\n"
        ),
    )

    ui_new_p.add_argument(
        "name",
        help="Project name (becomes the directory and class name)",
    )

    ui_new_p.add_argument(
        "--port",
        type=int,
        default=0,
        help="Port for the local dev server (default: auto)",
    )

    ui_new_p.add_argument(
        "--no-serve",
        action="store_true",
        help="Scaffold and compile only, do not start the dev server",
    )

    ui_new_p.add_argument(
        "--force",
        action="store_true",
        help="Overwrite an existing project directory",
    )

    ui_new_p.add_argument(
        "--fake-cloud",
        action="store_true",
        help=(
            "Serve the new project as `workpeg ui serve <name> --fake-cloud`\n"
            "does: a dev page at https://<namespace>.dev.workpeg.com"
        ),
    )

    ui_new_p.set_defaults(_handler="ui.new")

    ui_build_p = ui_sub.add_parser(
        "build",
        help="Compile a Python Peg UI app to JavaScript",
        formatter_class=argparse.RawTextHelpFormatter,
        epilog=(
            "Examples:\n"
            "  workpeg ui build counter/\n"
            "  workpeg ui build counter/ --out build\n"
            "  workpeg ui build counter/main.py\n"
        ),
    )

    ui_build_p.add_argument(
        "source",
        help=(
            "Project directory containing main.py, or an explicit .py source file"
        ),
    )

    ui_build_p.add_argument(
        "--out",
        default=None,
        help=(
            "Output directory for compiled files "
            "(default: dist/ inside the project directory)"
        ),
    )

    # Read from the environment so a dev image or test job sets this once
    # instead of every build remembering the flag. Read by the CLI, never by
    # the browser. argparse does not validate an env-supplied default against
    # choices=, so the ui.build handler re-checks args.chrome itself.
    ui_build_p.add_argument(
        "--chrome",
        choices=_CHROME_SOURCES,
        default=os.environ.get("WORKPEG_CHROME", "auto"),
        help=(
            "Where the built app loads its chrome from at runtime:\n"
            "  auto     (default) the CDN's current copy, with the app's\n"
            "           bundled copy as the fallback — the Workpeg team's\n"
            "           chrome updates reach the app without a rebuild\n"
            "  bundled  same-origin only, never the network: for local\n"
            "           development and tests. A released peg is never built\n"
            "           this way: it would never receive a chrome update\n"
            "Env: WORKPEG_CHROME."
        ),
    )

    ui_build_p.set_defaults(_handler="ui.build")

    ui_verify_p = ui_sub.add_parser(
        "verify",
        help="Check a built dist as Workpeg does before it goes live",
        formatter_class=argparse.RawTextHelpFormatter,
        epilog=(
            "Examples:\n"
            "  workpeg ui verify counter/dist --sdk 0.161.0\n"
            "  workpeg ui verify dist.tar --sdk 0.161.0 --namespace counter\n"
            "  workpeg ui verify --digests\n"
            "\n"
            "Exits 0 when every check passes, 1 when one fails, and 2 when\n"
            "it cannot check (a target other than the SDK installed here).\n"
            "Guide: docs/getting-started.md#workpeg-ui-verify\n"
        ),
    )
    ui_verify_p.add_argument(
        "dist", nargs="?", default=None,
        help="A built dist folder, or an uncompressed tar of one")
    ui_verify_p.add_argument(
        "--sdk", default=None, metavar="X.Y.Z",
        help="The SDK the dist was built with: the peg's target")
    ui_verify_p.add_argument(
        "--namespace", default=None,
        help="Also refuse a dist built as any other peg")
    ui_verify_p.add_argument(
        "--json", action="store_true",
        help="Print the report as JSON, with every file's sha256")
    ui_verify_p.add_argument(
        "--digests", action="store_true",
        help="Print this SDK's digest list as JSON, and check nothing")
    ui_verify_p.set_defaults(_handler="ui.verify")

    ui_serve_p = ui_sub.add_parser(
        "serve",
        help="Compile a Python Peg UI app and serve it on localhost",
        formatter_class=argparse.RawTextHelpFormatter,
        epilog=(
            "Examples:\n"
            "  workpeg ui serve counter/\n"
            "  workpeg ui serve counter/ --port 3000\n"
            "  workpeg ui serve counter/main.py\n"
            "  workpeg ui serve counter/dist/\n"
            "  workpeg ui serve counter/ --fake-cloud\n"
        ),
    )

    ui_serve_p.add_argument(
        "source",
        help=(
            "Project directory containing main.py (compile + live-reload), "
            "an explicit .py source file, "
            "or a pre-built dist directory (serve as-is)"
        ),
    )

    ui_serve_p.add_argument(
        "--port",
        type=int,
        default=0,
        help=("Port for the local server (default: auto). With --fake-cloud, "
              "443 only"),
    )

    ui_serve_p.add_argument(
        "--out",
        default=None,
        help=(
            "Output directory for compiled files when source is a .py file "
            "(default: dist/ next to the source file)"
        ),
    )

    ui_serve_p.add_argument(
        "--fake-cloud",
        action="store_true",
        help=(
            "Dev install: build the project exactly as `workpeg ui build`\n"
            "does and serve only that build at\n"
            "https://<namespace>.dev.workpeg.com, the namespace its\n"
            "workpeg.json declares, on port 443 and to this computer\n"
            "only, so the page reaches the API on the same domain as a\n"
            "released peg. Needs mkcert. Reads no token. Before anything\n"
            "is bound it refuses a name Workpeg keeps, a pre-built\n"
            "folder, --peg-namespace, a --port other than 443 and\n"
            "WORKPEG_BIND_HOST.\n"
            "Guide: docs/dev-install.md"
        ),
    )

    ui_serve_p.add_argument(
        "--peg-namespace",
        default=None,
        metavar="NAMESPACE",
        help=(
            "Run locally as the Peg NAMESPACE — the CDN logo, the workpeg.* "
            "namespace header, etc. resolve as if served from "
            "<NAMESPACE>.dev.workpeg.com (default: the project name). "
            "Applies when compiling a project/.py source, without "
            "--fake-cloud: a dev page takes its namespace from the project."
        ),
    )

    ui_serve_p.add_argument(
        "--listen",
        nargs="?",
        const="",
        default=None,
        metavar="FUNCTION_DIR",
        help=(
            "With --fake-cloud: also run the peg's function on this\n"
            "computer for your own saves (default FUNCTION_DIR: the\n"
            "function/ folder beside the project). Reads WORKPEG_PK"
        ),
    )
    _add_runner_options(ui_serve_p)

    # The 0.151 spelling of --fake-cloud, kept so that a command line
    # written then still works, and hidden: the one documented flag is
    # --fake-cloud (owner, 2026-11-08).
    ui_serve_p.add_argument(
        "--dev",
        action="store_true",
        help=argparse.SUPPRESS,
    )

    ui_serve_p.set_defaults(_handler="ui.serve")

    ui_dev_clean_p = ui_sub.add_parser(
        "dev-clean",
        help=(
            "Remove the hosts lines and certificates serve --fake-cloud "
            "wrote"
        ),
        formatter_class=argparse.RawTextHelpFormatter,
        epilog=(
            "Examples:\n"
            "  workpeg ui dev-clean counter/\n"
            "  workpeg ui dev-clean          # the current directory\n"
            "  workpeg ui dev-clean --all\n"
            "\n"
            "Only hosts lines marked '# workpeg-fake-cloud' are removed; a\n"
            "line you wrote yourself stays, even for the same name. mkcert's\n"
            "root CA stays too: `mkcert -uninstall` removes it.\n"
        ),
    )
    ui_dev_clean_p.add_argument(
        "project",
        nargs="?",
        default=None,
        help=(
            "Project directory, its main.py or its dist/ (default: .). "
            "It need not exist any more"
        ),
    )
    ui_dev_clean_p.add_argument(
        "--all",
        action="store_true",
        dest="all_names",
        help="Every marked hosts line and every dev certificate, any project",
    )
    ui_dev_clean_p.set_defaults(_handler="ui.dev-clean")

    #
    # DOCTOR
    #
    doctor_p = root_sub.add_parser(
        "doctor",
        help="Diagnose the SDK install, project, and CDN delivery",
        formatter_class=argparse.RawTextHelpFormatter,
        epilog=(
            "Examples:\n"
            "  workpeg doctor                # the current directory\n"
            "  workpeg doctor path/to/peg    # a specific project or dist\n"
            "  workpeg doctor --json         # machine-readable, for CI\n"
            "  workpeg doctor --strict       # warnings fail too (CI)\n"
            "\n"
            "Exit codes: 0 healthy (warnings allowed unless --strict),\n"
            "1 problems found, 2 doctor itself failed to run.\n"
        ),
    )
    doctor_p.add_argument(
        "path",
        nargs="?",
        default=".",
        help=(
            "Project directory, SDK checkout, or a prebuilt dist/ to "
            "diagnose (default: .)"
        ),
    )
    doctor_p.add_argument(
        "--verbose",
        action="store_true",
        help="Show skipped checks and per-check detail lines",
    )
    doctor_p.add_argument(
        "--json",
        action="store_true",
        help="Machine-readable output (stable check ids; no color)",
    )
    doctor_p.add_argument(
        "--offline",
        action="store_true",
        help="Skip the network checks without probing",
    )
    doctor_p.add_argument(
        "--strict",
        action="store_true",
        help=(
            "Exit 1 on warnings too (network warnings stay advisory — "
            "the CDN is gated by CI's canary, not by your wifi)"
        ),
    )
    doctor_p.add_argument(
        "--timeout",
        type=float,
        default=3.0,
        metavar="N",
        help="Per-probe network timeout in seconds (default: 3)",
    )
    doctor_p.set_defaults(_handler="doctor")

    return p


def _quoted(name) -> str:
    """A path the developer gave, as an error repeats it: quoted, or
    escaped whole when it holds anything unprintable."""
    from workpeg.ui.devmode import _q

    return _q(name)


#: What the runner calls when it stops on its own (a refusal, or another
#: listener taking over): the dev server in the main thread is interrupted
#: as Ctrl+C would, so the command ends with the runner's line.
def _wake_main() -> None:
    import _thread

    _thread.interrupt_main()


def _runner_checks(args) -> None:
    """The runner's option checks, before anything is read or run."""
    from workpeg import listen

    if args.debug and args.with_runtime != "process":
        raise listen.ListenRefused(listen.DEBUG_NEEDS_PROCESS)
    if args.concurrency is not None and not (
            1 <= args.concurrency <= listen.MAX_CONCURRENCY):
        raise listen.ListenRefused(listen.CONCURRENCY)


def _listen_key(argv) -> str:
    """The key, held in memory only. On the first pass the command
    re-executes itself without WORKPEG_PK in its environment, and this
    returns on the second."""
    from workpeg import listen

    key = listen.take_key()
    if key is not None:
        return key
    if listen.KEY_ENV not in os.environ or not os.environ[listen.KEY_ENV]:
        raise listen.ListenRefused(listen.NO_KEY)
    listen.reexec_without_key(list(argv), os.environ)
    raise SystemExit(2)  # pragma: no cover - execve does not return


def _sibling_function(source: str):
    import pathlib

    path = pathlib.Path(source).resolve()
    project = path if path.is_dir() else path.parent
    return project.parent / "function"


def _serve_dev_page(source: str, out: "str | None",
                    peg_namespace: "str | None", port: int, *,
                    function: "str | None" = None, runner_args=None,
                    argv=None) -> None:
    """``serve --fake-cloud``: a dev page at
    ``https://<namespace>.dev.workpeg.com``, built as a release is.

    The checks run first and bind nothing (:mod:`workpeg.ui.devmode`); then
    the release's build; then mkcert, the hosts line and the certificate,
    after the build so that a build that fails changes nothing on this
    computer (:mod:`workpeg.ui.devserve`); then port 443 behind the peer
    check, serving only what that build wrote (:mod:`workpeg.ui.devsite`).
    """
    from workpeg.ui import devmode, devserve, devsite
    from workpeg.ui.build import PublicAssetError
    from workpeg.ui.compiler.ast_parser import UnsupportedSyntaxError
    from workpeg.ui.actions_manifest import ActionValidationError
    from workpeg.ui.search_manifest import ManifestValidationError

    folder = None
    if function is not None:
        from workpeg import function_local, listen

        try:
            _runner_checks(runner_args)
            folder = function_local.function_folder(function)
        except (listen.ListenRefused, function_local.FunctionFolderError) \
                as refusal:
            print(f"ERROR: {shown_lines(refusal)}", file=sys.stderr)
            raise SystemExit(2)

    try:
        plan = devmode.preflight(
            source, peg_namespace=peg_namespace, port=port,
            environ=os.environ)
    except devmode.DevModeRefused as refusal:
        print(f"ERROR: {shown_lines(refusal)}", file=sys.stderr)
        raise SystemExit(2)
    _warn_dev_target(plan.entry)

    # After the checks, which cost nothing, and before the build: the first
    # pass re-executes the command without WORKPEG_PK in its environment.
    key = executor = None
    if folder is not None:
        try:
            key = _listen_key(argv)
            # Docker is asked before the build, so that a computer with no
            # Docker is told so at once.
            executor = listen.make_executor(
                runner_args.with_runtime or "docker", folder,
                plan.namespace, debug=runner_args.debug)
        except listen.ListenRefused as refusal:
            print(f"ERROR: {shown_lines(refusal)}", file=sys.stderr)
            raise SystemExit(2)

    out_dir = out or str(plan.entry.parent / "dist")
    try:
        # The release's build, whatever WORKPEG_CHROME says: the page
        # tested is the page shipped.
        devsite.release_build(plan.entry, out_dir)
    except (UnsupportedSyntaxError, SyntaxError, ManifestValidationError,
            ActionValidationError, PublicAssetError) as e:
        print(f"ERROR: {shown_lines(e)}", file=sys.stderr)
        raise SystemExit(2)

    runner = None
    if key is not None:
        runner = _start_runner(plan, folder, key, executor, runner_args)

    try:
        try:
            tls = devserve.prepare(plan)
        except devserve.DevServeRefused as refusal:
            print(f"ERROR: {shown_lines(refusal)}", file=sys.stderr)
            raise SystemExit(2)
        if runner is not None:
            runner.on_stop = _wake_main
            runner.start()
        _run_server(devserve.run, plan, out_dir, tls)
    finally:
        if runner is not None:
            runner.stop()
    if runner is not None and runner.exit_line:
        print(f"ERROR: {runner.exit_line}", file=sys.stderr)
        raise SystemExit(2)


def _start_runner(plan, folder, key, executor, args):
    """The function runner for *plan*'s dev install: its banner, its
    container in Docker mode, and its first poll, all before the page is
    served, so a refusal stops the command having served nothing."""
    from workpeg import listen
    from workpeg.ui import devserve

    try:
        concurrency = 1 if args.debug else (
            args.concurrency or listen.MAX_CONCURRENCY)
        runner = listen.Runner(
            namespace=plan.namespace, folder=folder, key=key,
            executor=executor, concurrency=concurrency,
            show_payload=args.show_payload,
            install_link=devserve.install_link(plan.namespace))
        if args.debug:
            runner.say(listen.DEBUG_NOTE)
        runner.prepare()
        runner.first_poll()
    except listen.ListenRefused as refusal:
        executor.stop()
        print(f"ERROR: {shown_lines(refusal)}", file=sys.stderr)
        raise SystemExit(2)
    except BaseException:
        executor.stop()           # Ctrl+C during the build, say
        raise
    return runner


def _dev_clean(args) -> None:
    """``workpeg ui dev-clean``: print what went, each name once and escaped,
    then the one thing that stays (mkcert's root CA)."""
    from workpeg.ui import fake_cloud

    if args.all_names and args.project is not None:
        print("ERROR: give either a project or --all, not both.",
              file=sys.stderr)
        raise SystemExit(2)
    project = None if args.all_names else (args.project or ".")
    shown = fake_cloud.escaped
    try:
        domains = None if project is None else fake_cloud.project_domains(
            project)
        removed, left = fake_cloud.dev_clean(domains)
    except (fake_cloud.FakeCloudError, OSError) as e:
        # OSError: a certificate folder that cannot be deleted, or a hosts
        # file that cannot be read, is one line, not a traceback.
        print(f"ERROR: {shown(e)}", file=sys.stderr)
        raise SystemExit(2)

    # A removed name passed the hostname check, so it is printable as is.
    for domain, what in removed:
        print(f"  Removed  {domain}  ({', '.join(what)})")
    for domain in left:
        print(
            f"WARNING: left {shown(domain)}: its marked line names a host "
            f"the SDK never writes, so it was edited by hand. Delete it "
            f"yourself if you no longer want it.",
            file=sys.stderr,
        )
    if not removed:
        whose = "any project" if project is None else shown(project)
        print(f"  Nothing the dev loop wrote is left for {whose}.")
    print(f"\n  {fake_cloud.MKCERT_STAYS}")


def _runner_flags_fit(args, *, listening: bool, dev: bool) -> bool:
    """``ui serve``'s runner options only with ``--listen``, and
    ``--listen`` only on a dev page. Prints the refusal and says False."""
    from workpeg import listen

    if listening and not dev:
        print("ERROR: --listen runs your function for a dev page: add "
              "--fake-cloud.", file=sys.stderr)
        return False
    if not listening:
        for option, given in (("--with", args.with_runtime is not None),
                              ("--concurrency", args.concurrency is not None),
                              ("--show-payload", args.show_payload),
                              ("--debug", args.debug)):
            if given:
                print("ERROR: " + listen.OPTIONS_NEED_LISTEN.format(
                    option=option), file=sys.stderr)
                return False
    return True


def _project_target(args) -> int:
    """``workpeg project target X.Y.Z``: rewrite the peg's ``sdk`` key, or
    refuse a version Workpeg will not build, leaving the file as it was."""
    from workpeg import target_sdk

    try:
        old, new = target_sdk.set_target(args.path, args.version)
    except target_sdk.TargetError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 2
    was = "not set" if old is None else old
    print(f"workpeg.json: sdk {was} -> {new}")
    _warn_target(new)
    return 0


def _project_registry(args) -> int:
    """``project submit``, ``status`` and ``versions``: the registry's
    connection errors in one sentence, as ``function submit`` gives them."""
    import requests

    from workpeg import project_submit

    try:
        if args._handler == "project.submit":
            return project_submit.main_submit(
                args.ref, path=args.path, dry_run=args.dry_run,
                api=args.api, timeout=args.timeout)
        if args._handler == "project.status":
            return project_submit.main_status(
                args.ref, path=args.path, as_json=args.json, api=args.api,
                timeout=args.timeout)
        return project_submit.main_versions(
            path=args.path, as_json=args.json, api=args.api,
            timeout=args.timeout)
    except requests.ConnectionError as exc:
        print(f"ERROR: could not reach the Workpeg registry: {exc}",
              file=sys.stderr)
        return 2
    except requests.Timeout:
        print("ERROR: request timed out.", file=sys.stderr)
        return 2


def _ui_verify(args) -> int:
    """``workpeg ui verify``: 0 when the dist passes every check, 1 when one
    fails, 2 when it cannot be checked as asked."""
    import json

    from workpeg.ui import verify

    if args.digests:
        if args.dist is not None or args.sdk is not None:
            print("ERROR: --digests prints this SDK's digest list and checks "
                  "nothing: drop the dist and --sdk.", file=sys.stderr)
            return 2
        print(json.dumps(verify.digest_list(), indent=2, sort_keys=True))
        return 0
    if args.dist is None or args.sdk is None:
        print("ERROR: name the dist and the SDK it was built with: "
              "`workpeg ui verify <dist> --sdk X.Y.Z`.", file=sys.stderr)
        return 2
    try:
        report = verify.verify(args.dist, args.sdk, namespace=args.namespace)
    except verify.VerifyError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 2
    if args.json:
        print(json.dumps(report.to_json(), indent=2, sort_keys=True))
    else:
        print(verify.render(report))
    return 0 if report.ok else 1


def _warn_target(target) -> None:
    """The one line when *target* is not the SDK installed here. A warning,
    never a refusal: the build that will count is Workpeg's, at the
    target."""
    from workpeg import target_sdk

    line = target_sdk.warning(target)
    if line:
        print(f"WARNING: {line}", file=sys.stderr)


def _warn_dev_target(entry) -> None:
    """``serve --fake-cloud``'s target warning, from the workpeg.json the
    build reads. A project with none has no namespace, which preflight has
    already refused, or takes it from its folder; either way there is no
    target to compare, and nothing is said."""
    from workpeg import target_sdk
    from workpeg.ui.build import _find_peg_config

    manifest = _find_peg_config(entry, warn=False)
    if manifest is None:
        return
    try:
        target = target_sdk.read_manifest(manifest)
    except target_sdk.TargetError:
        return            # the build reports an unreadable workpeg.json
    _warn_target(target)


def _project_serve(args, argv) -> None:
    """``workpeg project serve <peg> --fake-cloud``: ``<peg>/ui`` as a dev
    page, and ``<peg>/function`` for this person's own calls."""
    import pathlib

    peg = pathlib.Path(args.peg)
    if not args.fake_cloud:
        print("ERROR: project serve serves a dev page: add --fake-cloud.",
              file=sys.stderr)
        raise SystemExit(2)
    if not (peg / "ui").is_dir():
        print(f"ERROR: {_quoted(args.peg)} has no ui/ folder: pass the "
              f"peg's folder, the one `workpeg project create` made.",
              file=sys.stderr)
        raise SystemExit(2)
    function = None
    if (peg / "function" / "app" / "main.py").is_file():
        function = str(peg / "function")
    else:
        print("  This peg has no function/app/main.py, so only its page is "
              "served.", file=sys.stderr)
    _serve_dev_page(str(peg / "ui"), None, None, args.port,
                    function=function, runner_args=args, argv=argv)


def _function_test(args) -> int:
    """``workpeg function test``: one call, offline. The answer goes to
    stdout as JSON; the function's own output, escaped, to stderr."""
    import json
    import pathlib

    from workpeg import function_envelopes, function_local

    if args.envelope == "action" and not args.action:
        print("ERROR: --envelope action needs --action NAME.",
              file=sys.stderr)
        return 2
    try:
        folder = function_local.function_folder(args.path)
    except function_local.FunctionFolderError as e:
        print(f"ERROR: {e}", file=sys.stderr)
        return 2
    payload = {}
    if args.payload:
        try:
            payload = json.loads(
                pathlib.Path(args.payload).read_text(encoding="utf-8"))
        except (OSError, ValueError) as e:
            print(f"ERROR: {_quoted(args.payload)} cannot be read as JSON: "
                  f"{shown_lines(e)}", file=sys.stderr)
            return 2
        if not isinstance(payload, dict):
            print(f"ERROR: {_quoted(args.payload)} must hold a JSON object.",
                  file=sys.stderr)
            return 2
    envelope = function_envelopes.offline_envelope(
        args.envelope, phase=args.phase, action=args.action,
        namespace=function_local.namespace_of(folder) or folder.parent.name,
        payload=payload)
    answer = function_local.run_in_child(folder, envelope,
                                         timeout=args.timeout)
    for line in answer.output:
        print(f"  | {shown_lines(line)}", file=sys.stderr)
    print(json.dumps(answer.body), flush=True)
    return 0 if answer.status == 200 else 1


def _run_server(serve_fn, *args, **kwargs) -> None:
    """Run a blocking dev server, turning a ServeError (e.g. a privileged or
    in-use port) into a clean CLI error instead of a raw traceback."""
    from workpeg.ui.serve import ServeError

    try:
        serve_fn(*args, **kwargs)
    except ServeError as e:
        print(f"ERROR: {shown_lines(e)}", file=sys.stderr)
        raise SystemExit(1)


def main(argv=None) -> None:
    argv = argv if argv is not None else sys.argv[1:]

    parser = build_parser()

    if not argv:
        parser.print_help()
        return

    args = parser.parse_args(argv)

    if not hasattr(args, "_handler"):
        if hasattr(args, "_namespace_parser"):
            args._namespace_parser.print_help()
        else:
            parser.print_help()
        return

    #
    # doctor
    #

    if args._handler == "doctor":
        from workpeg import doctor  # lazy — keep `workpeg --help` fast

        try:
            code = doctor.run(args)
        except Exception:
            import traceback

            # A crash must not masquerade as a health verdict: exits 0/1 are
            # doctor's diagnosis, 2 means the diagnosis never happened.
            traceback.print_exc()
            print(
                "ERROR: doctor itself crashed — this is a doctor bug, "
                "not a verdict.",
                file=sys.stderr,
            )
            raise SystemExit(2)
        if code:
            raise SystemExit(code)
        return

    #
    # function new
    #

    if args._handler == "function.new":
        try:
            out = create_new.create_new_project(
                args.path,
                force=args.force,
            )
            print(str(out))
        except create_new.TemplateError as e:
            print(f"ERROR: {shown_lines(e)}", file=sys.stderr)
            raise SystemExit(2)
        return

    #
    # function runtime
    #

    if args._handler == "function.runtime":
        runtime_argv = []

        if args.server:
            runtime_argv.append("--server")

        runtime.main(runtime_argv)
        return

    if args._handler == "function.test":
        code = _function_test(args)
        if code:
            raise SystemExit(code)
        return

    #
    # function submit
    #

    if args._handler == "function.submit":
        import requests

        submit_argv = [args.ref]

        if args.branch is not None:
            submit_argv += ["--branch", args.branch]

        if args.api:
            submit_argv += ["--api", args.api]

        if args.path:
            submit_argv += ["--path", args.path]

        if args.timeout is not None:
            submit_argv += ["--timeout", str(args.timeout)]

        try:
            submit.main(submit_argv)
        except requests.ConnectionError as e:
            print(f"ERROR: could not reach the Workpeg registry: {e}", file=sys.stderr)
            raise SystemExit(2)
        except requests.Timeout:
            print("ERROR: request timed out.", file=sys.stderr)
            raise SystemExit(2)
        return

    #
    # function build
    #

    if args._handler == "function.build":
        try:
            image = build.build_image(
                path=args.path,
                tag=args.tag,
                like_workpeg=args.like_workpeg,
            )
            print(image)
        except (FileNotFoundError, NotADirectoryError, RuntimeError) as e:
            print(f"ERROR: {shown_lines(e)}", file=sys.stderr)
            raise SystemExit(2)
        return

    #
    # function run
    #

    if args._handler == "function.run":
        import subprocess

        run_argv = []

        if args.with_runtime:
            run_argv += ["--with", args.with_runtime]

        if args.path:
            run_argv += ["--path", args.path]

        if args.no_build:
            run_argv.append("--no-build")

        if args.network:
            run_argv += ["--network", args.network]

        if args.name:
            run_argv += ["--name", args.name]

        if args.no_expose:
            run_argv.append("--no-expose")

        try:
            run.main(run_argv)
        except (FileNotFoundError, NotADirectoryError, RuntimeError, NotImplementedError) as e:
            print(f"ERROR: {shown_lines(e)}", file=sys.stderr)
            raise SystemExit(2)
        except subprocess.CalledProcessError as e:
            print(
                f"ERROR: command failed (exit {e.returncode}). "
                "Check the output above for details.",
                file=sys.stderr,
            )
            raise SystemExit(2)
        return

    #
    # cdn submit
    #

    if args._handler == "cdn.submit":
        import requests

        cdn_argv = [args.source]

        if args.path:
            cdn_argv += ["--path", args.path]

        if args.api:
            cdn_argv += ["--api", args.api]

        if args.exact:
            cdn_argv.append("--exact")

        if args.overwrite:
            cdn_argv.append("--overwrite")

        if args.timeout is not None:
            cdn_argv += ["--timeout", str(args.timeout)]

        try:
            cdn.main(cdn_argv)
        except requests.ConnectionError as e:
            print(f"ERROR: could not reach the Workpeg registry: {e}", file=sys.stderr)
            raise SystemExit(2)
        except requests.Timeout:
            print("ERROR: request timed out.", file=sys.stderr)
            raise SystemExit(2)
        return

    #
    # ui new
    #

    if args._handler == "ui.new":
        import pathlib

        from workpeg.ui.build import PublicAssetError
        from workpeg.ui.create import ProjectExistsError, create_ui_project
        from workpeg.ui.compiler.ast_parser import UnsupportedSyntaxError

        from workpeg.starter import GUIDE_FILES, starter_files

        name = args.name

        print(f"Creating {name}...")

        # Asked before writing: an AGENTS.md or CLAUDE.md already here is
        # kept even under --force, and the person is told so.
        kept = [g for g in GUIDE_FILES if (pathlib.Path(name) / g).exists()]

        try:
            project_dir, source_file = create_ui_project(
                name, force=args.force
            )
        except ProjectExistsError as e:
            print(f"ERROR: {shown_lines(e)}", file=sys.stderr)
            raise SystemExit(2)
        except (UnsupportedSyntaxError, SyntaxError, PublicAssetError) as e:
            print(f"ERROR: {shown_lines(e)}", file=sys.stderr)
            raise SystemExit(2)

        rel = project_dir.name
        print()
        for guide in GUIDE_FILES:
            note = "   (kept yours)" if guide in kept else ""
            print(f"  {rel}/{guide}{note}")
        for path in starter_files():
            if not path.endswith("__init__.py"):
                print(f"  {rel}/{path}")
        print(f"  {rel}/dist/\n")
        if "AGENTS.md" not in kept:
            print("AGENTS.md tells a coding agent how to build this peg.\n")

        if args.no_serve:
            print(f"Done. Open {project_dir / 'dist' / 'index.html'} in a browser.")
            return

        # The starter uses the SDK Scaffold, which gates on a signed-in
        # session — a plain serve shows only the auth gate. --fake-cloud
        # serves it as a dev page, signed in, so the sidebar + pages render.
        if args.fake_cloud:
            _serve_dev_page(str(project_dir), None, None, args.port)
            return

        print("This starter uses the Workpeg Scaffold (sidebar + auth "
              "gate). To see the sidebar and pages, preview it with:")
        print(f"  workpeg ui serve {rel} --fake-cloud\n")

        from workpeg.ui.serve import serve_blocking

        # Watch the whole project directory so edits to any page file trigger
        # a recompile — not just changes to main.py.
        _run_server(
            serve_blocking,
            str(project_dir / "dist"),
            args.port,
            watch_source=str(project_dir),
        )
        return

    #
    # ui serve
    #

    if args._handler == "ui.dev-clean":
        _dev_clean(args)
        return

    if args._handler == "ui.serve":
        import pathlib

        from workpeg.ui.build import PublicAssetError
        from workpeg.ui.compiler.ast_parser import UnsupportedSyntaxError
        from workpeg.ui.actions_manifest import ActionValidationError
        from workpeg.ui.search_manifest import ManifestValidationError

        # What a build can fail with. Named rather than inlined: the
        # handlers sit at three nesting depths and no inline tuple
        # wraps cleanly at all of them.
        _BUILD_ERRORS = (
            UnsupportedSyntaxError, SyntaxError,
            ManifestValidationError, ActionValidationError,
            PublicAssetError,
        )
        from workpeg.ui.serve import serve_blocking

        dev = args.fake_cloud or args.dev
        if not _runner_flags_fit(args, listening=args.listen is not None,
                                 dev=dev):
            raise SystemExit(2)

        # A dev page. args.dev is the hidden 0.151 alias: the same path.
        if dev:
            function = None
            if args.listen is not None:
                function = args.listen or str(_sibling_function(args.source))
            elif (_sibling_function(args.source) / "app" / "main.py").is_file():
                print("  This peg has a function. Add --listen to run it for "
                      "your own saves, or run `workpeg project serve <peg> "
                      "--fake-cloud`.", file=sys.stderr)
            _serve_dev_page(args.source, args.out, args.peg_namespace,
                            args.port, function=function, runner_args=args,
                            argv=argv)
            return

        source = pathlib.Path(args.source)

        if not source.exists():
            print(f"ERROR: {_quoted(source)} does not exist.", file=sys.stderr)
            raise SystemExit(2)

        port = args.port
        peg_ns = args.peg_namespace

        if source.is_dir():
            main_py = source / "main.py"
            if main_py.exists():
                # Project directory — compile main.py, watch for changes, and serve.
                from workpeg.ui.build import build_ui

                out_dir = args.out or str(source / "dist")

                try:
                    # chrome_source="bundled": a dev loop must serve the
                    # scaffold.js on disk. With the editable install this repo
                    # uses, dist/scaffold.js IS the source file — defaulting to
                    # "auto" would let the CDN silently shadow the very edit
                    # you're previewing.
                    build_ui(str(main_py), out_dir, peg_namespace=peg_ns,
                             bundle_icons=True, chrome_source="bundled")
                except _BUILD_ERRORS as e:
                    print(f"ERROR: {shown_lines(e)}", file=sys.stderr)
                    raise SystemExit(2)

                # Watch the project directory, not just main.py, so edits to
                # any page file also trigger a recompile.
                _run_server(serve_blocking, out_dir, port,
                            watch_source=str(source),
                            peg_namespace=peg_ns)
            else:
                # No main.py — treat as a pre-built dist directory and serve
                # as-is, on localhost (a dev page refuses one). There's no
                # recompile, so --peg-namespace can't apply (the namespace
                # baked at build time stands).
                if peg_ns:
                    print("  Note: --peg-namespace is ignored for a pre-built "
                          "dist (rebuild to change it).", file=sys.stderr)
                _run_server(serve_blocking, str(source), port)

        elif source.suffix == ".py":
            from workpeg.ui.build import build_ui

            out_dir = args.out or str(source.parent / "dist")

            try:
                # See above: a dev loop serves the chrome on disk, not the
                # CDN's.
                build_ui(str(source), out_dir, peg_namespace=peg_ns,
                         bundle_icons=True, chrome_source="bundled")
            except _BUILD_ERRORS as e:
                print(f"ERROR: {shown_lines(e)}", file=sys.stderr)
                raise SystemExit(2)

            _run_server(serve_blocking, out_dir, port,
                        watch_source=str(source),
                        peg_namespace=peg_ns)

        else:
            print(
                f"ERROR: {_quoted(source)} is not a .py file or a directory. "
                "Pass a project directory, a .py source file, or a pre-built dist/ directory.",
                file=sys.stderr,
            )
            raise SystemExit(2)

        return

    #
    # ui build
    #

    if args._handler == "project.serve":
        _project_serve(args, argv)
        return

    if args._handler == "project.target":
        return _project_target(args)

    if args._handler in ("project.submit", "project.status",
                         "project.versions"):
        raise SystemExit(_project_registry(args))

    # project create
    if args._handler == "project.create":
        import pathlib

        from workpeg.project import ProjectError, create_project

        from workpeg.starter import GUIDE_FILES

        target = pathlib.Path(args.path or args.name)
        # Asked before writing: an existing guide is kept even with --force.
        kept = [g for g in GUIDE_FILES if (target / g).exists()]
        try:
            created = create_project(target, args.name, force=args.force)
        except ProjectError as exc:
            print(f"ERROR: {exc}", file=sys.stderr)
            return 2

        # A target submit would refuse (an SDK below the floor, read from a
        # stale install) is said now, not at the first submit. A target
        # that only differs from this SDK, as a dev tree's does, is not.
        from workpeg import target_sdk
        try:
            target_sdk.check(target_sdk.read(created))
        except target_sdk.TargetError as exc:
            print(f"WARNING: {exc}", file=sys.stderr)

        rel = os.path.relpath(created, pathlib.Path.cwd())
        print(f"Created {rel}/")
        print(f"  workpeg.json   namespace: {args.name}")
        for guide in GUIDE_FILES:
            if guide in kept:
                print(f"  {guide:<14} kept yours")
            elif guide == "AGENTS.md":
                print(f"  {guide:<14} how a coding agent should build it")
            else:
                print(f"  {guide:<14} imports AGENTS.md")
        print("  ui/            the interface, a Scaffold app")
        print("  function/      the backend")
        print("\nNext:")
        print(f"  workpeg ui serve {rel}/ui/ --fake-cloud")
        print(f"  workpeg project serve {rel}/ --fake-cloud")
        print(f"  workpeg function test {rel}/")
        print(f"  workpeg function run --path {rel}/function/")
        return

    if args._handler == "ui.verify":
        raise SystemExit(_ui_verify(args))

    if args._handler == "ui.build":
        import pathlib

        # argparse checks choices= only for a value it parsed off the command
        # line, never for the default — so WORKPEG_CHROME=garbage reaches us
        # unvalidated and would die as a raw ValueError traceback inside
        # build_ui. Catch it here, before the compiler import.
        if args.chrome not in _CHROME_SOURCES:
            print(
                f"ERROR: WORKPEG_CHROME={args.chrome} is not one of "
                f"{'|'.join(_CHROME_SOURCES)}.",
                file=sys.stderr,
            )
            raise SystemExit(2)

        from workpeg.ui.build import PublicAssetError, build_ui
        from workpeg.ui.compiler.ast_parser import UnsupportedSyntaxError
        from workpeg.ui.actions_manifest import ActionValidationError
        from workpeg.ui.search_manifest import ManifestValidationError

        # What a build can fail with. Named rather than inlined: the
        # handlers sit at three nesting depths and no inline tuple
        # wraps cleanly at all of them.
        _BUILD_ERRORS = (
            UnsupportedSyntaxError, SyntaxError,
            ManifestValidationError, ActionValidationError,
            PublicAssetError,
        )

        source_path = pathlib.Path(args.source)

        if not source_path.exists():
            print(f"ERROR: '{source_path}' does not exist.", file=sys.stderr)
            raise SystemExit(2)

        if source_path.is_dir():
            main_py = source_path / "main.py"
            if not main_py.exists():
                print(
                    f"ERROR: no main.py found in '{source_path}'",
                    file=sys.stderr,
                )
                raise SystemExit(2)
            out_arg = args.out or str(source_path / "dist")
            source_path = main_py
        else:
            out_arg = args.out or str(source_path.parent / "dist")

        try:
            out = build_ui(str(source_path), out_arg,
                           chrome_source=args.chrome)
            print(f"Built to {out}")
        except _BUILD_ERRORS as e:
            print(f"ERROR: {e}", file=sys.stderr)
            raise SystemExit(2)
        return
